## Set Up The Optional Slug Route

Create `src/routes/docs.{-$slug}.tsx`. The application owns this route because locale resolution, canonical origin, redirects, not-found behavior, and header actions are project decisions.

```tsx
import { createFileRoute, notFound, redirect } from "@tanstack/react-router";

import { LocaleSwitcher } from "@/components/ui/locale-switcher";
import { ThemeToggle } from "@/components/theme-toggle";
import {
  DocsLayout,
  DocsNotFound,
  DocsPage,
  docsSource,
  makeDocs,
  type DocsLocale,
} from "@/lib/docs";
import { getLocale } from "@/paraglide/runtime";

const docsLocale = (): DocsLocale =>
  getLocale() === "fr" ? "fr" : "en";

const docs = makeDocs({
  source: docsSource,
  basePath: "/docs",
  defaultSlug: "introduction",
  origin: "https://example.com",
  siteName: "Example Docs",
  sectionOrder: ["start", "guides", "operations", "reference"],
  github: { url: "https://github.com/example/project" },
});

export const Route = createFileRoute("/docs/{-$slug}")({
  loader: ({ params }) => {
    const resolution = docs.resolve(params.slug, docsLocale());
    if (!resolution) throw notFound();

    if (!resolution.canonical) {
      throw redirect({
        to: resolution.page.path,
        statusCode: 301,
      });
    }

    return resolution;
  },
  head: ({ loaderData }) => {
    const locale = loaderData?.page.locale ?? docsLocale();
    return docs.getHead({
      locale,
      ...(loaderData?.page ? { page: loaderData.page } : {}),
    });
  },
  component: DocsRoutePage,
  notFoundComponent: () => (
    <DocsNotFound docs={docs} locale={docsLocale()} />
  ),
});

function DocsRoutePage() {
  const resolution = Route.useLoaderData();

  return (
    <DocsLayout
      docs={docs}
      locale={resolution.page.locale}
      headerActions={
        <>
          <ThemeToggle />
          <LocaleSwitcher />
        </>
      }
    >
      <DocsPage docs={docs} resolution={resolution} />
    </DocsLayout>
  );
}
```

The optional segment makes `/docs` resolve `defaultSlug` and `/docs/operations` resolve the matching page. `docs.resolve` also identifies legacy aliases; redirect every non-canonical resolution permanently so only one URL is indexed.

